namespace Mems.Api.Data;

/// <summary>Describes one fictional sample candidate and its packaged portrait.</summary>
public record DemoCandidate(string Key, string Municipality, string Position, string Name, string Biography)
{
    public string PhotoUrl => $"/images/demo-candidates/demo-{Key}.jpg";
    public string Email => Key.Replace('-', '.') + "@example.org";
    public string Website => $"https://example.org/candidates/{Key}";
}

